namespace docking.options.editor;







using ghidra.framework;
using ghidra.framework.options;
using ghidra.util;

public class EditorInitializer : ModuleInitializer {

	/* @Override */
	public void run() {
		//
		// The PropertyEditorManager uses thread-specific context when registering and finding
		// property editors.  This method is called on the application loading thread, not the
		// Swing thread.  Further, property editors are used by the application from the Swing
		// thread.  Thus, it is possible that the Swing thread cannot see editors registered from
		// the application thread.  Running this on the Swing thread ensures the Swing thread's
		// ThreadGroupContext is used.
		//
		Swing.runNow(this.registerEditors);
	}

	private void registerEditors() {
		PropertyEditorManager.registerEditor(typeof(string), typeof(StringEditor));
		PropertyEditorManager.registerEditor(typeof(Color), typeof(ColorEditor));
		PropertyEditorManager.registerEditor(typeof(Font), typeof(FontEditor));
		PropertyEditorManager.registerEditor(typeof(Enum), typeof(EnumEditor));
		PropertyEditorManager.registerEditor(typeof(Boolean), typeof(BooleanEditor));
		PropertyEditorManager.registerEditor(typeof(Date), typeof(DateEditor));
		PropertyEditorManager.registerEditor(typeof(Integer), typeof(IntEditor));
		PropertyEditorManager.registerEditor(typeof(File), typeof(FileChooserEditor));
	}

	/* @Override */
	public string getName() {
		return "Property Editor Initializer";
	}
}
